/**
 * Jinx Mastermind + Vigormortis: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Mastermind
 * Wiki: https://wiki.bloodontheclocktower.com/Vigormortis
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { abilityState } from '#lib/core/rules/ability.ts';
import { keepsAbilityWhenDead } from '#lib/core/rules/dead-characters.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Mastermind + Vigormortis jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'mastermind', 'vigormortis');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('mastermind')?.name).toBe('Mastermind');
		expect(data.byId.get('vigormortis')?.name).toBe('Vigormortis');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['mastermind', 'vigormortis'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['mastermind'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['vigormortis'])).not.toContain(jinx);
	});

	describe('a Mastermind the Vigormortis killed keeps their ability if the Vigormortis dies', () => {
		const ids = ['vigormortis', 'mastermind', 'poisoner', 'chef', 'empath', 'monk'];
		// The Vigormortis killed the Mastermind and the Poisoner: both keep their ability.
		const killed = scenario(ids, { script: scriptOf(ids) })
			.dies('mastermind', 'vigormortis')
			.reminder('mastermind', 'vigormortis', 'Has Ability')
			.dies('poisoner', 'vigormortis')
			.reminder('poisoner', 'vigormortis', 'Has Ability');
		const keeps = (s: Scenario, who: string) =>
			keepsAbilityWhenDead(s.game, s.seat(who), s.characters);

		it("is data in the Mastermind's rules", () => {
			// Wiki: "A Mastermind that has their ability keeps it if the Vigormortis dies."
			expect(ownJinxRules(killed.game, 'mastermind', 'vigormortis', killed.characters)).toEqual({
				keepsAbility: { afterDeath: true }
			});
		});

		it('keeps the Mastermind’s ability after the Vigormortis dies', () => {
			// Wiki: "A Mastermind that has their ability keeps it if the Vigormortis dies."
			expect(keeps(killed, 'mastermind')).toBe(true);
			const s = killed.execute('vigormortis');
			expect(keeps(s, 'mastermind')).toBe(true);
			expect(abilityState(s.game, s.seat('mastermind'), s.characters).dead).toBe(false);
		});

		it('takes it from another Minion the Vigormortis killed, as usual', () => {
			// Wiki: "A Mastermind that has their ability keeps it"
			const s = killed.execute('vigormortis');
			expect(keeps(killed, 'poisoner')).toBe(true);
			expect(keeps(s, 'poisoner')).toBe(false);
		});
	});
});
